<script>
document.addEventListener('DOMContentLoaded', function () {
    const tabs = document.querySelector('.vc_tta');
    if (!tabs) return;

    tabs.querySelectorAll('a[href^="#law-"]').forEach(function (link) {
        link.setAttribute('href', 'department-of-law/' + link.getAttribute('href'));
    });

    function showLawPanel(panelId, updateUrl) {
        const panel = document.getElementById(panelId);
        if (!panel || !panel.closest('.vc_tta')) return;

        tabs.querySelectorAll('.vc_tta-tab').forEach(function (tab) {
            tab.classList.remove('vc_active');
        });
        tabs.querySelectorAll('.vc_tta-panel').forEach(function (item) {
            item.classList.remove('vc_active');
        });

        panel.classList.add('vc_active');
        const tabLink = tabs.querySelector('.vc_tta-tab a[href$="#' + panelId + '"]');
        if (tabLink) tabLink.closest('.vc_tta-tab').classList.add('vc_active');

        if (updateUrl && window.history && window.history.replaceState) {
            window.history.replaceState(null, '', 'department-of-law/#' + panelId);
        }
    }

    document.addEventListener('click', function (event) {
        const link = event.target.closest('.vc_tta a[href*="#law-"]');
        if (!link) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        showLawPanel(link.getAttribute('href').split('#').pop(), true);
    }, true);

    if (window.location.hash.indexOf('#law-') === 0) {
        showLawPanel(window.location.hash.slice(1), false);
    }
});
</script>

